import {Capacitor} from './capacitor-core.mjs';
import {NativeFamilyBrand as exportsPlugin} from './family-icons.mjs';
async function androidExport(blob){const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(blob)});await exportsPlugin.shareExport({type:blob.type,data})}
export async function saveBlob(blob,name){if(Capacitor.getPlatform()==='android'){await androidExport(blob);return}const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
export function canvasBlob(canvas){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('تعذّر إنشاء الصورة')),'image/jpeg',.92))}
export async function picture(url){const r=await fetch(url);if(!r.ok)throw Error('تعذّر تحميل الصورة');return createImageBitmap(await r.blob())}
export function textLines(ctx,text,width){const lines=[];for(const paragraph of String(text||'').split('\n')){let line='';for(const word of paragraph.split(/\s+/)){if(ctx.measureText(word).width>width){if(line){lines.push(line);line=''}let part='';for(const ch of word){if(ctx.measureText(part+ch).width>width){lines.push(part);part=''}part+=ch}line=part;continue}const next=line?line+' '+word:word;if(ctx.measureText(next).width>width&&line){lines.push(line);line=word}else line=next}lines.push(line)}return lines}
export function jpegPDF(pages,width=1190.55,height=841.89){const enc=new TextEncoder(),chunks=[],offsets=[0];let size=0;const add=x=>{const bytes=typeof x==='string'?enc.encode(x):x;chunks.push(bytes);size+=bytes.length},obj=(id,head,data)=>{offsets[id]=size;add(id+' 0 obj\n'+head);if(data){add('\nstream\n');add(data);add('\nendstream')}add('\nendobj\n')};add('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Count '+pages.length+' /Kids ['+pages.map((_,i)=>(3+i*3)+' 0 R').join(' ')+'] >>');pages.forEach((p,i)=>{const id=3+i*3;obj(id,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+width+' '+height+'] /Resources << /XObject << /Im '+(id+1)+' 0 R >> >> /Contents '+(id+2)+' 0 R >>');obj(id+1,'<< /Type /XObject /Subtype /Image /Width '+p.width+' /Height '+p.height+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+p.bytes.length+' >>',p.bytes);const command=enc.encode('q '+width+' 0 0 '+height+' 0 0 cm /Im Do Q');obj(id+2,'<< /Length '+command.length+' >>',command)});const start=size;add('xref\n0 '+offsets.length+'\n0000000000 65535 f \n');for(const offset of offsets.slice(1))add(String(offset).padStart(10,'0')+' 00000 n \n');add('trailer\n<< /Size '+offsets.length+' /Root 1 0 R >>\nstartxref\n'+start+'\n%%EOF');return new Blob(chunks,{type:'application/pdf'})}
export async function shareFile(blob,name){if(Capacitor.getPlatform()==='android'){await androidExport(blob);return}const file=new File([blob],name,{type:blob.type});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'أخبار العائلة'})}else saveBlob(blob,name)}
